/**
 * Mission-Driven Boustrophedon Field Rover Simulator.
 *
 * Unlike a blind random-walk demo, this simulator executes an actual Boustrophedon
 * (serpentine) Mission generated by the BEV Path Planner (or a default 3m × 2m 4-row mission):
 *   - Follows ordered FollowRow segments straight down each crop row corridor
 *   - Monitors the dynamic AttentionWindow near row end before executing headland turns
 *   - Executes planned 90° -> cross gapM -> 90° Headland Turns between rows
 *   - Runs the STOP -> SCAN -> AIM -> FIRE loop with overlapping 40×30cm downward camera frames
 *     and calibrated rover-frame pan/tilt aiming while protecting every tomato crop plant
 */

import { buildDefaultFieldMission } from './boustrophedon';
import { Field, Mission, PathSegment } from './models';

export type RoverState =
  | 'IDLE'
  | 'FOLLOW_ROW'
  | 'STOP'
  | 'SCAN'
  | 'AIM'
  | 'FIRE'
  | 'HEADLAND_TURN'
  | 'DONE';

export interface SimPlant {
  id: number;
  x: number; // cm along row (field length)
  y: number; // cm across rows (field width)
  radiusCm: number;
}

export interface DetectedWeed {
  weedId: number;
  u: number;
  v: number;
  rxCm: number;
  ryCm: number;
  x: number;
  y: number;
  radiusCm: number;
  confidence: number;
}

export interface RoverStats {
  ticks: number;
  steps: number;
  scans: number;
  weedsFound: number;
  weedsFired: number;
  headlandTurns: number;
  rowsCompleted: number;
  distanceTravelledM: number;
}

export interface SimLogEntry {
  tick: number;
  state: RoverState;
  message: string;
}

export interface RoverSimSnapshot {
  seed: number;
  mission: Mission;
  isCustomMission: boolean;
  fieldWCm: number; // along row (lengthM * 100)
  fieldHCm: number; // across rows (widthM * 100)
  camViewWCm: number;
  camViewHCm: number;
  frameW: number;
  frameH: number;
  roverX: number;
  roverY: number;
  heading: number; // degrees: 0 = +X, 90 = +Y, 180 = -X, 270 = -Y
  state: RoverState;
  running: boolean;
  eStopped: boolean;
  activeSegmentIndex: number;
  totalSegments: number;
  currentRow: number;
  totalRows: number;
  rowProgressM: number;
  rowLengthM: number;
  inAttentionWindow: boolean;
  panDeg: number;
  tiltDeg: number;
  aimPixel: { u: number; v: number } | null;
  laserFiring: boolean;
  lastLaserHit: { x: number; y: number } | null;
  eliminatedPositions: { x: number; y: number }[];
  tofDistanceMm: number;
  crops: SimPlant[];
  weeds: SimPlant[];
  initialWeedCount: number;
  pendingWeeds: DetectedWeed[];
  trail: { x: number; y: number }[];
  stats: RoverStats;
  logs: SimLogEntry[];
}

type TurnSubPhase = 'ROTATE_1' | 'CROSS_GAP' | 'ROTATE_2';

export const DEFAULT_SIM_FIELD: Field = {
  widthM: 2.4,
  lengthM: 3.6,
  totalRows: 4,
  rowSpacingM: 0.6,
  originCorner: 'TOP_LEFT',
};

function createMulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export class RoverFieldSimulation {
  readonly camViewWCm = 40.0;
  readonly camViewHCm = 30.0;
  readonly frameW = 640;
  readonly frameH = 480;
  readonly laserMountHeightCm = 24.0;
  readonly fireDistanceMm = 110;

  private rng: () => number;
  private seed: number;

  mission: Mission;
  isCustomMission = false;

  fieldWCm = 360.0;
  fieldHCm = 240.0;
  stepDistCm = 24.0;

  roverX = 0.0;
  roverY = 30.0;
  heading = 0.0;

  activeSegmentIndex = 0;
  rowProgressM = 0;
  inAttentionWindow = false;
  private rowEndReached = false;
  private turnSubPhase: TurnSubPhase = 'ROTATE_1';

  crops: SimPlant[] = [];
  weeds: SimPlant[] = [];
  eliminatedPositions: { x: number; y: number }[] = [];
  initialWeedCount = 0;

  state: RoverState = 'IDLE';
  running = false;
  eStopped = false;

  panDeg = 90;
  tiltDeg = 60;
  aimPixel: { u: number; v: number } | null = null;
  laserFiring = false;
  lastLaserHit: { x: number; y: number } | null = null;
  tofDistanceMm = 800;

  pendingWeeds: DetectedWeed[] = [];
  currentWeedIdx = 0;
  trail: { x: number; y: number }[] = [];

  stats: RoverStats = {
    ticks: 0,
    steps: 0,
    scans: 0,
    weedsFound: 0,
    weedsFired: 0,
    headlandTurns: 0,
    rowsCompleted: 0,
    distanceTravelledM: 0,
  };

  logs: SimLogEntry[] = [];

  constructor(seed = 42, customMission?: Mission | null) {
    this.seed = seed;
    this.rng = createMulberry32(seed);
    this.mission = customMission ?? buildDefaultFieldMission(DEFAULT_SIM_FIELD);
    this.isCustomMission = Boolean(customMission);
    this.reset(seed, customMission);
  }

  private uniform(min: number, max: number): number {
    return min + this.rng() * (max - min);
  }

  private log(message: string) {
    this.logs.unshift({
      tick: this.stats.ticks,
      state: this.state,
      message,
    });
    if (this.logs.length > 50) {
      this.logs.pop();
    }
  }

  loadMission(mission: Mission | null, seed = this.seed) {
    this.reset(seed, mission);
  }

  reset(seed = this.seed, customMission?: Mission | null) {
    this.seed = seed;
    this.rng = createMulberry32(seed);

    if (customMission !== undefined) {
      this.mission = customMission ?? buildDefaultFieldMission(DEFAULT_SIM_FIELD);
      this.isCustomMission = Boolean(customMission);
    }

    this.fieldWCm = Math.max(100, this.mission.field.lengthM * 100);
    this.fieldHCm = Math.max(100, this.mission.field.widthM * 100);

    // Overlap camera swath cleanly (max ~70% of camViewWCm so zero weeds slip between scans)
    this.stepDistCm = Math.min(this.camViewWCm * 0.68, Math.max(18, this.fieldWCm / 20));

    this.activeSegmentIndex = 0;
    this.rowProgressM = 0;
    this.inAttentionWindow = false;
    this.rowEndReached = false;
    this.turnSubPhase = 'ROTATE_1';

    const firstSeg = this.mission.path[0];
    if (firstSeg) {
      this.roverX = firstSeg.startPoint.x * 100;
      this.roverY = firstSeg.startPoint.y * 100;
      this.heading = firstSeg.endPoint.x >= firstSeg.startPoint.x ? 0 : 180;
    } else {
      this.roverX = 0;
      this.roverY = this.fieldHCm / 2;
      this.heading = 0;
    }

    this.crops = [];
    this.weeds = [];
    this.eliminatedPositions = [];
    this.pendingWeeds = [];
    this.currentWeedIdx = 0;
    this.state = 'IDLE';
    this.running = false;
    this.eStopped = false;
    this.panDeg = 90;
    this.tiltDeg = 60;
    this.aimPixel = null;
    this.laserFiring = false;
    this.lastLaserHit = null;
    this.tofDistanceMm = 800;
    this.trail = [{ x: this.roverX, y: this.roverY }];
    this.stats = {
      ticks: 0,
      steps: 0,
      scans: 0,
      weedsFound: 0,
      weedsFired: 0,
      headlandTurns: 0,
      rowsCompleted: 0,
      distanceTravelledM: 0,
    };
    this.logs = [];

    this.generateStructuredField();
    this.initialWeedCount = this.weeds.length;
    const rowCount = this.mission.path.filter((s) => s.type === 'FollowRow').length;
    this.log(
      `Loaded Boustrophedon mission (${this.mission.field.lengthM.toFixed(1)}m × ${this.mission.field.widthM.toFixed(1)}m, ${rowCount} rows, ${this.mission.path.length} segments) — ${this.crops.length} tomato plants, ${this.weeds.length} weeds`
    );
  }

  private nearAny(items: SimPlant[], x: number, y: number, minDist: number): boolean {
    const d2 = minDist * minDist;
    return items.some((it) => (x - it.x) ** 2 + (y - it.y) ** 2 < d2);
  }

  /**
   * Populate tomato crops along the exact planned FollowRow lines (straddle-rover crop geometry)
   * and scatter weeds inside the row corridors where the downward 40×30cm camera sweeps.
   */
  private generateStructuredField() {
    const rowSegs = this.mission.path.filter((s) => s.type === 'FollowRow');
    let cropId = 1;

    // Space tomato plants evenly along each crop row
    const plantSpacingCm = Math.max(28, Math.min(44, this.fieldWCm / 11));
    rowSegs.forEach((seg) => {
      const rowYCm = seg.startPoint.y * 100;
      const minX = Math.min(seg.startPoint.x, seg.endPoint.x) * 100;
      const maxX = Math.max(seg.startPoint.x, seg.endPoint.x) * 100;

      let x = minX + 20;
      while (x < maxX - 14) {
        this.crops.push({
          id: cropId++,
          x,
          y: rowYCm + this.uniform(-1.5, 1.5),
          radiusCm: this.uniform(5.0, 7.0),
        });
        x += plantSpacingCm + this.uniform(-3.0, 3.0);
      }
    });

    // Scatter weeds along the crop-row corridors (within camera lateral swath ±12cm)
    const targetWeeds = Math.min(36, Math.max(16, rowSegs.length * 5));
    let weedId = 1;
    const halfLateralSwath = Math.min(this.camViewHCm * 0.42, (this.mission.field.rowSpacingM * 100) * 0.35);

    for (let i = 0; i < targetWeeds && rowSegs.length > 0; i++) {
      const seg = rowSegs[i % rowSegs.length];
      const rowYCm = seg.startPoint.y * 100;
      const minX = Math.min(seg.startPoint.x, seg.endPoint.x) * 100 + 18;
      const maxX = Math.max(seg.startPoint.x, seg.endPoint.x) * 100 - 18;

      for (let attempt = 0; attempt < 40; attempt++) {
        const wx = this.uniform(minX, Math.max(minX + 5, maxX));
        const wy = Math.max(
          8,
          Math.min(this.fieldHCm - 8, rowYCm + this.uniform(-halfLateralSwath, halfLateralSwath))
        );
        if (this.nearAny(this.crops, wx, wy, 8.5)) continue;
        if (this.nearAny(this.weeds, wx, wy, 9.0)) continue;
        this.weeds.push({
          id: weedId++,
          x: wx,
          y: wy,
          radiusCm: this.uniform(3.2, 5.2),
        });
        break;
      }
    }
  }

  private worldToRoverFrame(wx: number, wy: number): { rxCm: number; ryCm: number } {
    const dx = wx - this.roverX;
    const dy = wy - this.roverY;
    const rad = (this.heading * Math.PI) / 180;
    return {
      rxCm: dx * Math.cos(rad) + dy * Math.sin(rad),
      ryCm: -dx * Math.sin(rad) + dy * Math.cos(rad),
    };
  }

  worldToFrame(wx: number, wy: number): { u: number; v: number; rxCm: number; ryCm: number } {
    const { rxCm, ryCm } = this.worldToRoverFrame(wx, wy);
    const pxPerCmX = this.frameW / this.camViewWCm;
    const pxPerCmY = this.frameH / this.camViewHCm;
    return {
      u: Math.round(rxCm * pxPerCmX + this.frameW / 2),
      v: Math.round(ryCm * pxPerCmY + this.frameH / 2),
      rxCm,
      ryCm,
    };
  }

  private weedsInFrame(): SimPlant[] {
    const halfW = this.camViewWCm / 2;
    const halfH = this.camViewHCm / 2;
    return this.weeds.filter((w) => {
      const { rxCm, ryCm } = this.worldToRoverFrame(w.x, w.y);
      return Math.abs(rxCm) <= halfW && Math.abs(ryCm) <= halfH;
    });
  }

  private currentSegment(): PathSegment | null {
    return this.mission.path[this.activeSegmentIndex] ?? null;
  }

  private centerGimbal() {
    this.panDeg = 90;
    this.tiltDeg = 60;
    this.aimPixel = null;
  }

  emergencyStop() {
    this.eStopped = true;
    this.running = false;
    this.laserFiring = false;
    this.centerGimbal();
    this.state = 'IDLE';
    this.log('*** EMERGENCY STOP ACTIVATED ***');
  }

  clearEmergencyStop() {
    this.eStopped = false;
    this.log('Safety interlock reset — ready to resume mission');
  }

  private advanceAfterFollowRow() {
    this.stats.rowsCompleted++;
    this.rowEndReached = false;
    this.inAttentionWindow = false;
    this.activeSegmentIndex++;

    const next = this.currentSegment();
    if (!next) {
      this.state = 'DONE';
      this.running = false;
      this.centerGimbal();
      this.log(
        `MISSION COMPLETE — ${this.stats.rowsCompleted} rows covered, ${this.stats.weedsFired}/${this.initialWeedCount} weeds eliminated`
      );
      return;
    }

    if (next.type === 'Turn') {
      this.turnSubPhase = 'ROTATE_1';
      this.state = 'HEADLAND_TURN';
      this.log(
        `Row-end confirmed in Attention Window → starting ${next.direction} headland turn (gap=${next.gapM.toFixed(2)}m)`
      );
    } else {
      this.rowProgressM = 0;
      this.state = 'FOLLOW_ROW';
    }
  }

  tick() {
    if (this.eStopped) {
      this.running = false;
      return;
    }

    if (this.state === 'DONE') {
      this.running = false;
      return;
    }

    this.stats.ticks++;
    this.laserFiring = false;

    const seg = this.currentSegment();
    if (!seg) {
      this.state = 'DONE';
      this.running = false;
      return;
    }

    switch (this.state) {
      case 'IDLE': {
        if (seg.type === 'FollowRow') {
          this.heading = seg.endPoint.x >= seg.startPoint.x ? 0 : 180;
          this.log(`Starting Seg #${seg.seq}: FollowRow ${seg.row} (heading=${this.heading}°)`);
          this.state = 'SCAN';
        } else {
          this.turnSubPhase = 'ROTATE_1';
          this.state = 'HEADLAND_TURN';
        }
        break;
      }

      case 'FOLLOW_ROW': {
        if (seg.type !== 'FollowRow') {
          this.turnSubPhase = 'ROTATE_1';
          this.state = 'HEADLAND_TURN';
          break;
        }

        const targetX = seg.endPoint.x * 100;
        const targetY = seg.endPoint.y * 100;
        const dx = targetX - this.roverX;
        const dy = targetY - this.roverY;
        const distRemainingCm = Math.hypot(dx, dy);

        this.heading = seg.endPoint.x >= seg.startPoint.x ? 0 : 180;

        const moveCm = Math.min(this.stepDistCm, distRemainingCm);
        if (distRemainingCm > 0.1) {
          this.roverX += (dx / distRemainingCm) * moveCm;
          this.roverY += (dy / distRemainingCm) * moveCm;
          this.stats.distanceTravelledM += moveCm / 100;
          this.trail.push({ x: this.roverX, y: this.roverY });
          if (this.trail.length > 800) this.trail.shift();
        }

        this.rowProgressM = Math.hypot(
          this.roverX - seg.startPoint.x * 100,
          this.roverY - seg.startPoint.y * 100
        ) / 100;

        const wasInWin = this.inAttentionWindow;
        this.inAttentionWindow =
          this.rowProgressM >= this.mission.attentionWindow.startM &&
          this.rowProgressM <= this.mission.attentionWindow.endM;

        if (!wasInWin && this.inAttentionWindow) {
          this.log(
            `Entered Attention Window [${this.mission.attentionWindow.startM.toFixed(1)}m–${this.mission.attentionWindow.endM.toFixed(1)}m] on Row ${seg.row}`
          );
        }

        this.tofDistanceMm = this.inAttentionWindow ? 1250 : 820;
        this.stats.steps++;
        this.rowEndReached = distRemainingCm - moveCm <= 0.5;
        this.state = 'STOP';
        break;
      }

      case 'STOP': {
        this.state = 'SCAN';
        break;
      }

      case 'SCAN': {
        this.stats.scans++;
        const visible = this.weedsInFrame();
        if (visible.length === 0) {
          this.pendingWeeds = [];
          if (this.rowEndReached) {
            this.advanceAfterFollowRow();
          } else {
            this.state = 'FOLLOW_ROW';
          }
          break;
        }

        this.pendingWeeds = visible.map((w) => {
          const { u, v, rxCm, ryCm } = this.worldToFrame(w.x, w.y);
          return {
            weedId: w.id,
            u,
            v,
            rxCm,
            ryCm,
            x: w.x,
            y: w.y,
            radiusCm: w.radiusCm,
            confidence: Math.min(0.99, Math.max(0.78, (w.radiusCm / 5.2) * 0.96)),
          };
        });
        this.currentWeedIdx = 0;
        this.stats.weedsFound += this.pendingWeeds.length;
        this.log(
          `SCAN (Row ${seg.type === 'FollowRow' ? seg.row : '-'}) found ${this.pendingWeeds.length} weed(s) — tomato crops shielded`
        );
        this.state = 'AIM';
        break;
      }

      case 'AIM': {
        if (this.currentWeedIdx >= this.pendingWeeds.length) {
          this.centerGimbal();
          if (this.rowEndReached) {
            this.advanceAfterFollowRow();
          } else {
            this.state = 'FOLLOW_ROW';
          }
          break;
        }

        const target = this.pendingWeeds[this.currentWeedIdx];
        // Calibrated rover-frame angular inverse kinematics (cm -> servo degrees)
        const panOffsetDeg = (Math.atan2(target.rxCm, this.laserMountHeightCm) * 180) / Math.PI;
        const tiltOffsetDeg = (Math.atan2(target.ryCm, this.laserMountHeightCm) * 180) / Math.PI;
        this.panDeg = Math.round(Math.max(15, Math.min(165, 90 + panOffsetDeg)));
        this.tiltDeg = Math.round(Math.max(20, Math.min(120, 60 + tiltOffsetDeg)));
        this.aimPixel = { u: target.u, v: target.v };
        this.log(
          `AIM → rover(${target.rxCm.toFixed(1)}, ${target.ryCm.toFixed(1)})cm · pan=${this.panDeg}° tilt=${this.tiltDeg}°`
        );
        this.state = 'FIRE';
        break;
      }

      case 'FIRE': {
        const target = this.pendingWeeds[this.currentWeedIdx];
        this.tofDistanceMm = this.fireDistanceMm + Math.round(this.uniform(-4, 4));
        const safeDepth = Math.abs(this.tofDistanceMm - this.fireDistanceMm) <= 50;

        if (safeDepth && target) {
          this.laserFiring = true;
          const idx = this.weeds.findIndex((w) => w.id === target.weedId);
          if (idx >= 0) {
            const removed = this.weeds.splice(idx, 1)[0];
            this.lastLaserHit = { x: removed.x, y: removed.y };
            this.eliminatedPositions.push({ x: removed.x, y: removed.y });
            this.stats.weedsFired++;
            this.log(
              `FIRE (ToF=${this.tofDistanceMm}mm) → Weed #${removed.id} eliminated (${this.weeds.length} remaining)`
            );
          }
        }

        this.currentWeedIdx++;
        if (this.currentWeedIdx < this.pendingWeeds.length) {
          this.state = 'AIM';
        } else {
          this.pendingWeeds = [];
          this.centerGimbal();
          if (this.rowEndReached) {
            this.advanceAfterFollowRow();
          } else {
            this.state = 'FOLLOW_ROW';
          }
        }
        break;
      }

      case 'HEADLAND_TURN': {
        if (seg.type !== 'Turn') {
          this.state = 'FOLLOW_ROW';
          break;
        }
        const targetY = seg.endPoint.y * 100;
        const targetX = seg.endPoint.x * 100;
        const crossHeading = targetY >= this.roverY ? 90 : 270;

        if (this.turnSubPhase === 'ROTATE_1') {
          this.heading = crossHeading;
          this.turnSubPhase = 'CROSS_GAP';
          this.log(`Headland Turn (${seg.direction}) — rotated 90° to heading=${this.heading}°`);
        } else if (this.turnSubPhase === 'CROSS_GAP') {
          const dy = targetY - this.roverY;
          const distCm = Math.abs(dy);
          const stepY = Math.min(20, distCm);
          if (distCm > 0.1) {
            this.roverY += Math.sign(dy) * stepY;
            this.roverX = targetX;
            this.stats.distanceTravelledM += stepY / 100;
            this.trail.push({ x: this.roverX, y: this.roverY });
            if (this.trail.length > 800) this.trail.shift();
          }
          if (distCm - stepY <= 0.5) {
            this.roverY = targetY;
            this.turnSubPhase = 'ROTATE_2';
          }
        } else {
          this.stats.headlandTurns++;
          this.activeSegmentIndex++;
          const next = this.currentSegment();
          if (next && next.type === 'FollowRow') {
            this.heading = next.endPoint.x >= next.startPoint.x ? 0 : 180;
            this.rowProgressM = 0;
            this.inAttentionWindow = false;
            this.rowEndReached = false;
            this.log(
              `Headland Turn complete — aligned to Row ${next.row} (heading=${this.heading}°)`
            );
            this.state = 'SCAN';
          } else {
            this.state = 'DONE';
            this.running = false;
          }
        }
        break;
      }
    }
  }

  getSnapshot(): RoverSimSnapshot {
    const seg = this.currentSegment();
    const rowSegs = this.mission.path.filter((s) => s.type === 'FollowRow');
    let currentRow = rowSegs.length;
    if (seg?.type === 'FollowRow') {
      currentRow = seg.row;
    } else if (seg?.type === 'Turn') {
      const next = this.mission.path[this.activeSegmentIndex + 1];
      currentRow = next?.type === 'FollowRow' ? next.row : rowSegs.length;
    }

    return {
      seed: this.seed,
      mission: this.mission,
      isCustomMission: this.isCustomMission,
      fieldWCm: this.fieldWCm,
      fieldHCm: this.fieldHCm,
      camViewWCm: this.camViewWCm,
      camViewHCm: this.camViewHCm,
      frameW: this.frameW,
      frameH: this.frameH,
      roverX: this.roverX,
      roverY: this.roverY,
      heading: this.heading,
      state: this.state,
      running: this.running,
      eStopped: this.eStopped,
      activeSegmentIndex: Math.min(this.activeSegmentIndex, Math.max(0, this.mission.path.length - 1)),
      totalSegments: this.mission.path.length,
      currentRow,
      totalRows: rowSegs.length,
      rowProgressM: this.rowProgressM,
      rowLengthM: this.mission.field.lengthM,
      inAttentionWindow: this.inAttentionWindow,
      panDeg: this.panDeg,
      tiltDeg: this.tiltDeg,
      aimPixel: this.aimPixel ? { ...this.aimPixel } : null,
      laserFiring: this.laserFiring,
      lastLaserHit: this.lastLaserHit ? { ...this.lastLaserHit } : null,
      eliminatedPositions: [...this.eliminatedPositions],
      tofDistanceMm: this.tofDistanceMm,
      crops: [...this.crops],
      weeds: [...this.weeds],
      initialWeedCount: this.initialWeedCount,
      pendingWeeds: [...this.pendingWeeds],
      trail: [...this.trail],
      stats: { ...this.stats },
      logs: [...this.logs],
    };
  }
}
